// Verificar firma Stripe HMAC-SHA256 con timingSafeEqual.
// Stripe-Signature header: t=...,v1=...
// Compute: HMAC_SHA256(secret, `${t}.${rawBody}`) === v1
//
// Fixes aplicados (Fase A audit):
//   S1.4 — usa crypto.timingSafeEqual en vez de !== para evitar timing-attacks.
//   S1.5 — fuerza rawBody a string UTF-8 si llega como Buffer.

const crypto = require('crypto');

const signature = $input.item.json.headers['stripe-signature'];
const rawBodyRaw = $input.item.json.body;
const secret = $env.STRIPE_WEBHOOK_SECRET;

if (!signature || !secret) {
  throw new Error('Falta stripe-signature header o STRIPE_WEBHOOK_SECRET');
}

// S1.5 — normalizar rawBody a string UTF-8 (n8n a veces lo da como Buffer).
let rawBody;
if (typeof rawBodyRaw === 'string') {
  rawBody = rawBodyRaw;
} else if (Buffer.isBuffer(rawBodyRaw)) {
  rawBody = rawBodyRaw.toString('utf8');
} else {
  // Si n8n ya parseó el JSON, lo reserializamos. Esto es subóptimo pero rescatable.
  rawBody = JSON.stringify(rawBodyRaw);
}

const parts = signature.split(',').reduce((acc, part) => {
  const idx = part.indexOf('=');
  if (idx === -1) return acc;
  acc[part.slice(0, idx)] = part.slice(idx + 1);
  return acc;
}, {});

if (!parts.t || !parts.v1) {
  throw new Error('Stripe-Signature mal formado');
}

const signedPayload = `${parts.t}.${rawBody}`;
const expected = crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');

// S1.4 — comparación timing-safe.
const expectedBuf = Buffer.from(expected, 'hex');
const receivedBuf = Buffer.from(parts.v1, 'hex');
if (expectedBuf.length !== receivedBuf.length || !crypto.timingSafeEqual(expectedBuf, receivedBuf)) {
  throw new Error('Firma Stripe inválida — posible spoofing');
}

// Anti-replay: rechazar eventos > 5 min
const now = Math.floor(Date.now() / 1000);
if (now - parseInt(parts.t, 10) > 300) {
  throw new Error('Webhook expirado (> 5 min)');
}

const event = JSON.parse(rawBody);
return {
  type: event.type,
  event_id: event.id,
  data: event.data.object,
  created: event.created
};

// Procesar checkout.session.completed:
//   1. Extraer datos del session
//   2. (S1.3) Idempotencia se chequea en el siguiente nodo Notion antes de crear cliente
//   3. Crear cliente en Notion (DB Clientes)
//   4. Disparar workflow Onboarding

const session = $input.item.json.data;
const event_id = $input.item.json.event_id;
const metadata = session.metadata || {};

return {
  event_id,
  email: session.customer_email || session.customer_details?.email,
  nombre: session.customer_details?.name || '',
  stripe_customer_id: session.customer,
  stripe_session_id: session.id,
  amount_total: session.amount_total / 100,
  currency: session.currency,
  producto: metadata.producto || 'desconocido',
  con_instalacion: metadata.con_instalacion === 'true',
  lead_id: metadata.lead_id || null,
  tiene_mantenimiento: session.mode === 'subscription' || !!session.subscription,
  stripe_subscription_id: session.subscription || null,
  fecha_compra: new Date(session.created * 1000).toISOString().split('T')[0]
};

// invoice.payment_failed → marcar cliente en-riesgo + alerta
const invoice = $input.item.json.data;
return {
  stripe_customer_id: invoice.customer,
  amount_due: invoice.amount_due / 100,
  attempt_count: invoice.attempt_count,
  next_payment_attempt: invoice.next_payment_attempt ? new Date(invoice.next_payment_attempt * 1000).toISOString() : null
};

