const sub = $input.item.json.data;
return {
  stripe_subscription_id: sub.id,
  stripe_customer_id: sub.customer,
  cancelled_at: new Date(sub.canceled_at * 1000).toISOString().split('T')[0],
  reason: sub.cancellation_details?.reason || 'desconocida'
};
